-- ==============================================================================
-- SAKUIN DASHBOARD - RELATIONAL SCHEMA (AUTO-INCREMENTAL IDENTITY PRIMARY KEYS)
-- ==============================================================================
-- 3 Tabel Normalisasi:
-- 1. categories     : Master Kategori (id BIGINT GENERATED BY DEFAULT AS IDENTITY)
-- 2. merchants      : Daftar Merchant (id BIGINT GENERATED BY DEFAULT AS IDENTITY, category_id BIGINT)
-- 3. sub_merchants  : Alias / Sub-Merchant (id BIGINT GENERATED BY DEFAULT AS IDENTITY, merchant_id BIGINT)
-- ==============================================================================

-- Reset Tabel Sebelumnya (Clean Slate)
DROP TABLE IF EXISTS public.transactions CASCADE;
DROP TABLE IF EXISTS public.sub_merchants CASCADE;
DROP TABLE IF EXISTS public.merchants CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;

-- 1. Tabel categories
CREATE TABLE public.categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  api_category_name TEXT,
  description TEXT,
  icon_type TEXT NOT NULL DEFAULT 'image',
  icon_name TEXT,
  icon_src TEXT,
  color TEXT NOT NULL DEFAULT 'blue',
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 2. Tabel merchants (Relasi ke categories)
CREATE TABLE public.merchants (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  logo_url TEXT,
  logo_dark_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 3. Tabel sub_merchants (Tabel terpisah untuk alias/sub-merchant, NO JSON)
CREATE TABLE public.sub_merchants (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  merchant_id BIGINT NOT NULL REFERENCES public.merchants(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 4. Tabel transactions (Riwayat Transaksi Kartu SakuCard)
CREATE TABLE public.transactions (
  id TEXT PRIMARY KEY,
  merchant TEXT NOT NULL,
  category_id BIGINT REFERENCES public.categories(id) ON DELETE SET NULL,
  category_slug TEXT,
  category TEXT NOT NULL,
  date TEXT NOT NULL,
  amount TEXT NOT NULL,
  currency TEXT NOT NULL DEFAULT 'Rp',
  status TEXT NOT NULL DEFAULT 'Success' CHECK (status IN ('Declined', 'Success', 'Pending')),
  reason TEXT,
  card_last4 TEXT NOT NULL DEFAULT '1995',
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Index Relasi
CREATE INDEX idx_merchants_category_id ON public.merchants(category_id);
CREATE INDEX idx_sub_merchants_merchant_id ON public.sub_merchants(merchant_id);
CREATE INDEX idx_transactions_category_id ON public.transactions(category_id);
CREATE INDEX idx_transactions_card_last4 ON public.transactions(card_last4);
CREATE INDEX idx_transactions_created_at ON public.transactions(created_at DESC);

-- 5. Row Level Security (RLS) Configuration
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.merchants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sub_merchants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;

-- Policies: categories
CREATE POLICY "Public select categories" ON public.categories FOR SELECT USING (true);
CREATE POLICY "Public insert categories" ON public.categories FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update categories" ON public.categories FOR UPDATE USING (true);
CREATE POLICY "Public delete categories" ON public.categories FOR DELETE USING (true);

-- Policies: merchants
CREATE POLICY "Public select merchants" ON public.merchants FOR SELECT USING (true);
CREATE POLICY "Public insert merchants" ON public.merchants FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update merchants" ON public.merchants FOR UPDATE USING (true);
CREATE POLICY "Public delete merchants" ON public.merchants FOR DELETE USING (true);

-- Policies: sub_merchants
CREATE POLICY "Public select sub_merchants" ON public.sub_merchants FOR SELECT USING (true);
CREATE POLICY "Public insert sub_merchants" ON public.sub_merchants FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update sub_merchants" ON public.sub_merchants FOR UPDATE USING (true);
CREATE POLICY "Public delete sub_merchants" ON public.sub_merchants FOR DELETE USING (true);

-- Policies: transactions
CREATE POLICY "Public select transactions" ON public.transactions FOR SELECT USING (true);
CREATE POLICY "Public insert transactions" ON public.transactions FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update transactions" ON public.transactions FOR UPDATE USING (true);
CREATE POLICY "Public delete transactions" ON public.transactions FOR DELETE USING (true);

