-- 10. Tabel guides (Panduan & Tutorial Interaktif)
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.guides (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title TEXT NOT NULL,
  banner_url TEXT NOT NULL,
  short_description TEXT NOT NULL,
  content_html TEXT NOT NULL,
  is_hidden BOOLEAN NOT NULL DEFAULT false,
  is_highlight BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX IF NOT EXISTS idx_guides_created_at ON public.guides(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_guides_is_hidden ON public.guides(is_hidden);
CREATE INDEX IF NOT EXISTS idx_guides_is_highlight ON public.guides(is_highlight);

ALTER TABLE public.guides ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public select guides" ON public.guides FOR SELECT USING (true);
CREATE POLICY "Public insert guides" ON public.guides FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update guides" ON public.guides FOR UPDATE USING (true);
CREATE POLICY "Public delete guides" ON public.guides FOR DELETE USING (true);

